// ─── File: JwtAnatomyDemo.java ───
// Runnable demo: build header.payload.signature; prove payload is readable, not secret.
package com.bank.jwtanatomy;

import java.util.*;
import java.util.logging.*;

public class JwtAnatomyDemo {

    private static final Logger log = Logger.getLogger("JwtAnatomy");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        log.setUseParentHandlers(false);
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        JwtCodec codec = new JwtCodec("nbin-hmac-secret");

        // SAFE payload: identity + authorization only — no sensitive data.
        JwtHeader header = new JwtHeader("HS256", "JWT");
        JwtClaims safe = new JwtClaims("SAV2001", Set.of("CUSTOMER"),
                "nbin-auth", "accounts-api", System.currentTimeMillis() + 900_000);
        String token = codec.create(header, safe);
        log.info(() -> "JWT (3 dot-separated parts): " + token);

        // Anyone holding the token can DECODE the payload — it is NOT encrypted.
        JwtClaims readBack = codec.decodePayload(token);
        log.warning(() -> "Payload is READABLE by anyone: sub=" + readBack.subject
                + ", roles=" + readBack.roles + "  → NEVER put secrets here");

        // Signature guarantees INTEGRITY: tamper the role → verification FAILS.
        String tampered = codec.tamperRoleToAdmin(token);
        log.info(() -> "verify original  → " + codec.verify(token));
        log.severe(() -> "verify tampered (role→ADMIN) → " + codec.verify(tampered)
                + " (rejected: signature no longer matches)");

        // The DANGEROUS payload a developer must NOT create.
        JwtClaims dangerous = new JwtClaims("SAV2001", Set.of("CUSTOMER"),
                "nbin-auth", "accounts-api", System.currentTimeMillis() + 900_000);
        dangerous.dangerousExtra = "balance=1000000; card=4111111111111111";
        log.severe("ANTI-PATTERN: balance + full card in payload would be readable by anyone");
    }
}

// ─── model/JwtHeader.java ───
class JwtHeader {
    final String alg, typ;
    JwtHeader(String alg, String typ) { this.alg = alg; this.typ = typ; }
    String toJson() { return "{\"alg\":\"" + alg + "\",\"typ\":\"" + typ + "\"}"; }
}

// ─── model/JwtClaims.java (the payload: registered + custom claims) ───
class JwtClaims {
    final String subject;         // sub — user/account id
    final Set<String> roles;      // private claim — authorization
    final String issuer;          // iss
    final String audience;        // aud
    final long expiry;            // exp
    String dangerousExtra;        // ← demonstrates what must NOT be stored
    JwtClaims(String sub, Set<String> roles, String iss, String aud, long exp) {
        this.subject = sub; this.roles = roles; this.issuer = iss; this.audience = aud; this.expiry = exp;
    }
    String toJson() {
        return "{\"sub\":\"" + subject + "\",\"roles\":\"" + String.join(",", roles)
                + "\",\"iss\":\"" + issuer + "\",\"aud\":\"" + audience + "\",\"exp\":" + expiry + "}";
    }
}

// ─── crypto/JwtCodec.java (Base64Url encode/decode + HMAC sign/verify) ───
class JwtCodec {
    private final String secret;
    JwtCodec(String secret) { this.secret = secret; }
    private String b64(String s) { return Base64.getUrlEncoder().withoutPadding()
            .encodeToString(s.getBytes()); }
    private String unb64(String s) { return new String(Base64.getUrlDecoder().decode(s)); }
    private String sign(String data) { return b64(Integer.toHexString((data + secret).hashCode())); }

    String create(JwtHeader h, JwtClaims c) {
        String data = b64(h.toJson()) + "." + b64(c.toJson());
        return data + "." + sign(data);                 // header.payload.signature
    }
    JwtClaims decodePayload(String token) {
        String json = unb64(token.split("\\.")[1]);     // ANYONE can do this — not secret
        // (parse omitted for brevity; return a representative object)
        String sub = json.split("\"sub\":\"")[1].split("\"")[0];
        String roles = json.split("\"roles\":\"")[1].split("\"")[0];
        return new JwtClaims(sub, new HashSet<>(Arrays.asList(roles.split(","))),
                "nbin-auth", "accounts-api", 0);
    }
    boolean verify(String token) {
        String[] p = token.split("\\.");
        return sign(p[0] + "." + p[1]).equals(p[2]);     // recompute + compare
    }
    // Attacker edits the payload to escalate role; signature will no longer match.
    String tamperRoleToAdmin(String token) {
        String[] p = token.split("\\.");
        String json = unb64(p[1]).replace("CUSTOMER", "ADMIN");
        return p[0] + "." + b64(json) + "." + p[2];      // old signature kept → invalid
    }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
